(function(){'use strict';
var config=window.SUITE_SUPABASE_CONFIG||{},token='',data=null;
function el(tag,text,cls){var n=document.createElement(tag);if(text!==undefined&&text!==null)n.textContent=text;if(cls)n.className=cls;return n}
function escDate(value){if(!value)return 'Sin fecha';var d=new Date(value.length===10?value+'T12:00:00':value);return isNaN(d)?'Fecha no disponible':new Intl.DateTimeFormat('es-AR',{dateStyle:'long',...(String(value).includes('T')?{timeStyle:'short'}:{})}).format(d)}
function size(value){var n=Number(value)||0;return n>=1048576?(n/1048576).toFixed(1)+' MiB':Math.ceil(n/1024)+' KiB'}
function safeSignedUrl(value){var base=new URL(config.url),url=new URL(String(value||''),base.origin);if(url.origin!==base.origin||!url.pathname.startsWith('/storage/v1/object/sign/')||!url.searchParams.has('token'))throw new Error('Supabase devolvió una URL de descarga inválida.');return url.href}
function say(message){var n=document.querySelector('#portal-alert');n.textContent=message;n.hidden=false}
async function request(body){var response=await fetch(config.url.replace(/\/$/,'')+'/functions/v1/tresor-portal',{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json'},body:JSON.stringify(body),cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});var result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'No se pudo consultar la documentación.');return result}
function card(title,cls){var a=el('section',null,'portal-card'+(cls?' '+cls:''));a.append(el('h2',title));return a}
function render(){var root=document.querySelector('#portal-content');root.replaceChildren();document.querySelector('#portal-alert').hidden=true;
 var trip=data.trip;root.append(el('section',null,'portal-hero'));var hero=root.lastChild;hero.append(el('p','TRESOR TRAVEL','portal-eyebrow'),el('h1',trip.trip_name||trip.destination||'Tu viaje'),el('p',trip.destination||''),el('div',(escDate(trip.departure_on)+' — '+escDate(trip.return_on)),'portal-dates'));
 var passengers=card('Pasajeros','');var names=el('ul');(data.passengers||[]).forEach(p=>names.append(el('li',p.name||'Pasajero')));if(!names.children.length)names.append(el('li','Pasajeros del viaje'));passengers.append(names);root.append(passengers);
 var docs=card('Tu documentación','');if(!(data.documents||[]).length)docs.append(el('p','Todavía no hay documentos generales disponibles. Consultá con Javier si esperabas recibir un archivo.','portal-muted'));
 (data.documents||[]).forEach(doc=>{var row=el('article',null,'portal-document');var detail=el('div');detail.append(el('strong',doc.title||doc.file_name),el('span',(doc.category||'Documento')+' · '+size(doc.size_bytes)));var button=el('button','Descargar PDF','portal-download');button.type='button';button.dataset.documentId=doc.id;row.append(detail,button);docs.append(row)});root.append(docs);
 if((data.reservations||[]).length){var air=card('Reservas aéreas','');(data.reservations||[]).forEach(r=>{var item=el('article',null,'portal-reservation');item.append(el('h3',(r.airline_name||'Aerolínea')+' · PNR '+(r.pnr||'—')));if(r.passengers?.length)item.append(el('p','Pasajeros: '+r.passengers.join(', ')));if(r.checkin_opens_at)item.append(el('p','Check-in desde: '+escDate(r.checkin_opens_at)));if(r.official_checkin_url){var a=el('a','Abrir web check-in oficial');a.href=r.official_checkin_url;a.target='_blank';a.rel='noopener noreferrer';item.append(a)}(r.flights||[]).forEach(f=>item.append(el('p',(f.flight_number?f.flight_number+' · ':'')+f.origin+' → '+f.destination+' · '+escDate(f.departure_at)+' — '+escDate(f.arrival_at))));air.append(item)});root.append(air)}
}
async function download(button){var tab=window.open('about:blank','_blank');if(!tab){say('Permití una ventana emergente para descargar el PDF.');return}tab.opener=null;button.disabled=true;try{var out=await request({action:'download',token,documentId:button.dataset.documentId});tab.location.replace(safeSignedUrl(out.signedUrl))}catch(error){tab.close();say(error.message||'No se pudo preparar la descarga.')}finally{button.disabled=false}}
async function init(){var fragment=location.hash.slice(1);history.replaceState(null,'',location.pathname);if(!fragment){say('Este enlace no contiene una clave de acceso válida. Pedile a Javier que verifique el enlace.');return}token=fragment;try{if(!config.url||!config.publishableKey)throw new Error('El portal todavía no está configurado.');var out=await request({action:'view',token});data=out.data;render()}catch(error){say(error.message||'Este enlace no está disponible o fue revocado.')}}
document.addEventListener('click',event=>{var b=event.target.closest('[data-document-id]');if(b)download(b)});init();
})();
